SourceCode.Declaration:
public class TFMPageConfigurationAttributeAttribute extends SysAttribute implements SysExtensionIAttribute
{
    str				xPath;
    anytype			defaultValue;
    str				nodeName;
    boolean			mandatory;
    boolean			editable;
    boolean         visibleWhenNoData;
    boolean			excludeFromXmlOutput;
    boolean			xmlOutputOnPage;

}

Method.Source:
void new(anyType _defaultValue, str _xPath, str _nodeName = '', boolean _mandatory = false, boolean _editable = true, boolean _excludeFromXmlOutput = false, boolean _visibleWhenNoData = false, boolean _xmlOutputOnPage = false)
{
    super();
    defaultValue         = _defaultValue;
    xPath                = _xPath;
    nodeName             = _nodeName;
    mandatory            = _mandatory;
    editable             = _editable;
    excludeFromXmlOutput = _excludeFromXmlOutput;
    visibleWhenNoData    = _visibleWhenNoData;
    xmlOutputOnPage      = _xmlOutputOnPage;
}

public str parmXPath(str _xPath = xPath)
{
    xPath = _xPath;

    return xPath;
}

public boolean parmMandatory(boolean _mandatory = mandatory)
{
    mandatory = _mandatory;
    return mandatory;
}

public boolean parmVisibleWhenNoData(boolean _visibleWhenNoData = visibleWhenNoData)
{
    visibleWhenNoData = _visibleWhenNoData;
    return visibleWhenNoData;
}

	/// <summary>
    /// Indicates whether an attribute is editable by user. This normally means, that the attribute is handled by the system, and shouldn't be made available for edit
    /// </summary>
    /// <param name = "_editable">true if attribute should be made available for edit. Otherwise false.</param>
    /// <returns></returns>
    public boolean parmEditable(boolean _editable = editable)
    {
        editable = _editable;
        return editable;
    }

public boolean parmExcludeFromXmlOutput(boolean _excludeFromXmlOutput = excludeFromXmlOutput)
{
    excludeFromXmlOutput = _excludeFromXmlOutput;
    return excludeFromXmlOutput;
}

/// <summary>
/// The element should be placed on the page element instead of the configuration element. E.g. warnonnavigatingback
/// </summary>
public boolean parmXmlOutputOnPage(boolean _xmlOutputOnPage = xmlOutputOnPage)
{
    xmlOutputOnPage = _xmlOutputOnPage;
    return xmlOutputOnPage;
}

public str parmnodeName(str _nodeName = nodeName)
{
    nodeName = _nodeName;
    return nodeName;
}

public anyType parmDefaultValue(anyType _defaultValue = defaultValue)
{
    defaultValue = _defaultValue;
    return defaultValue;
}
